#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        vector<int> res;
        for(int i=n-y;i<n;i++) res.push_back(p[i]);
        for(int i=x;i<n-y;i++) res.push_back(p[i]);
        for(int i=0;i<x;i++) res.push_back(p[i]);
        p=res;
        ops.push_back({x,y});
    };

    for(int placed=0;placed<n;placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: move element to position 'placed'
        // Remaining subarray is p[placed..n-1], length L = n - placed
        // Element is at position pos in global array
        // We want it at position placed

        // Idea: use x = pos, y = n - 1 - pos if possible (put 1 element in suffix at pos)
        // That puts p[n-1] at front... not helpful directly.

        // Move to front first: set y = n - pos (suffix = p[pos..n-1]), x = anything 1..pos-1
        // After: element at position 0. Need pos >= 2 for x>=1 and x+y<n.

        if(pos>=2){
            apply(1, n-pos); // element goes to position 0
            // Now move from 0 to placed: x=1, y = n-1-placed, need 1+n-1-placed<n => placed>0
            if(placed>0){
                apply(placed, 1); // suffix=p[n-1], mid=p[placed..n-2], prefix=p[0..placed-1] with elem at 0 -> goes to end n-1... wrong
                // x=1(prefix with element), y=n-1-placed: result=[suffix|mid|element]. element at pos n-1... 
                // Actually: x=placed, y=1. [C=p[n-1]|B=p[placed..n-2]|A=p[0..placed-1]]. Element at 0 is in A, goes to position n-placed. Hmm.
                // Let me just: x=1, y=n-1-placed => C=p[placed+1..n-1], B=p[1..placed], A=p[0]. Result: p[placed+1..n-1],p[1..placed],p[0]. Element(at 0) goes to n-1. Not good.
                // x=placed+1,y=n-placed-1: but x+y=n, invalid. Need middle.
                // Rethink: from pos 0 to placed. x=1, y=n-placed-1 if placed+2<=n. Element goes to end... nope.
            }
        }
        // Fallback: bubble
        if(pos!=placed) for(int i=pos;i>placed;i--) if(i>=2) apply(i-1,n-i);
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
